set -Eeuo pipefail
sudo -n /usr/bin/python3 - <<'PY'
import os,subprocess,json,stat
from pathlib import Path
root=Path('/srv/projects/telegram-robot-leads')
source_data=Path('/var/lib/telegram-robot-leads')
source_vault=Path('/root/project-secrets/telegram-robot-leads')
pm_home=root/'.pm2'
print('PROJECT',str(root),'EXISTS',root.is_dir(),'MODE',oct(root.stat().st_mode&0o777) if root.exists() else '?')
for typ,path in [('source_data',source_data),('source_vault',source_vault),('target_data',root/'data'),('target_private',root/'private'),('target_pm2',pm_home)]:
 print('STATE_PATH',typ,'PRESENT',path.exists(),'SYMLINK',path.is_symlink(),
  'OWN',str(path.lstat().st_uid)+':'+str(path.lstat().st_gid) if path.exists() else '-',
  'MODE',oct(path.lstat().st_mode & 0o777) if path.exists() else '-')
 if path.is_dir() and not path.is_symlink():
  print('STATE_CONTENT_COUNTS',typ, 'FILES',sum(len(files) for _,_,files in os.walk(path,followlinks=False)),'SESSIONS',len(list(path.rglob('*.session'))))
print('===PM2 PROCESS METADATA===')
r=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=15)
if r.returncode:raise RuntimeError('PM2 jlist failed')
for a in json.loads(r.stdout):
 if a.get('name') not in ('telegram-robot-leads','iptvpn_bot'):continue
 e=a.get('pm2_env') or {}
 print('APP',a.get('name'),'STATUS',e.get('status'),'PID',a.get('pid'),'EXE',e.get('pm_exec_path'),'CWD',e.get('pm_cwd'),'INTERPRETER',e.get('exec_interpreter'),'ARGS_META',str(e.get('args'))[:200])
 print('PM2_HOME_KEY','PRESENT' if 'PM2_HOME' in e else 'ABSENT')
print('===PHYSICAL OPENS TO SESSION / STATE===')
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  r=(proc/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
  if 'python3 -' in r or 'bash -lc' in r:continue
  if not ('telegram' in r.lower() or 'iptvpn' in r.lower() or 'pm2' in r.lower()):continue
  dirs=[]
  try:
   for fd in (proc/'fd').iterdir():
    try:
     q=os.readlink(fd)
     if str(source_vault) in q or str(source_data) in q:dirs.append('VAULT' if str(source_vault) in q else 'DATA')
    except OSError:pass
  except OSError:pass
  print('PROCESS',proc.name,'CLASS',('LEADS' if 'telegram' in r.lower() else 'OTHER'),'PRIVATE_OPEN_HANDLES',len(dirs))
 except OSError:pass
print('===VAULT AND DATA USAGE IN CODE===')
needle=[str(source_vault),str(source_data),'/opt/telegram-robot-leads','/srv/projects/telegram-robot-leads']
roots=[root/'scripts',root/'main.py',root/'ecosystem.config.js']
count={}
for base in roots:
 all_files=[base] if base.is_file() else [q for q in base.rglob('*') if q.is_file() and not q.is_symlink() and '__pycache__' not in q.parts] if base.is_dir() else []
 for p in all_files:
  try:
   if p.stat().st_size>300000 or p.suffix not in ('.py','.js','.sh','.md','.toml','.json','.yml','.yaml'):continue
   t=p.read_text(errors='replace')
   hits={s:t.count(s) for s in needle if s in t}
   if hits:
    print('SOURCE_REFS',str(p.relative_to(root)),json.dumps(hits))
    for s,k in hits.items():count[s]=count.get(s,0)+k
  except OSError:pass
print('REFERENCES_TOTALS',json.dumps(count))
print('===PM2 DUMP BASIC===')
d=Path('/root/.pm2/dump.pm2')
if d.is_file():
 try:
  j=json.loads(d.read_text())
  print('DUMP_APP_NAMES',[a.get('name') for a in j])
  for a in j:
   if a.get('name')=='telegram-robot-leads':
    print('DUMP_TELEGRAM_SCRIPT_META',a.get('pm_exec_path'),a.get('pm_cwd'))
 except (ValueError,OSError):print('DUMP_UNREADABLE')
print('===SYSTEMD SUPERVISOR===')
for unit in ['pm2-root.service','telegram-leads-activate-20261020.service','telegram-leads-activate-20261020.timer']:
 p=Path('/etc/systemd/system')/unit
 if p.is_file():
  t=p.read_text(errors='replace')
  print('UNIT',unit,'LENGTH',len(t),'LEADS_PATH_REFS',t.count('/opt/telegram-robot-leads'),'PM2_HOME_REFS',t.count('PM2_HOME'))
print('===CHECK ESSENTIAL BINARIES===')
for p in ['/usr/lib/node_modules/pm2/bin/pm2', '/usr/bin/node',str(root/'.venv/bin/python')]:
 q=Path(p)
 print('BIN',p,'EXISTS',q.exists(),'SYMLINK',q.is_symlink())
print('TELEGRAM_CUTOVER_PREFLIGHT_READONLY=PASS')
PY
